/* /* */
#include <iostream>
#include <string>
#include <algorithm>
int main(int argc, char** argv) {
    int n = argc > 1 ? std::stoi(argv[1]) : 0;
    std::string a = "1", b = "1";
    for (int i = 0; i < n; ++i) {
        std::string c;
        int carry = 0;
        int la = (int)a.size(), lb = (int)b.size();
        for (int j = 0; j < std::max(la, lb); ++j) {
            int x = carry;
            if (j < la) x += a[la - 1 - j] - '0';
            if (j < lb) x += b[lb - 1 - j] - '0';
            c.push_back(char('0' + x % 10));
            carry = x / 10;
        }
        if (carry) c.push_back(char('0' + carry));
        std::reverse(c.begin(), c.end());
        a = b; b = c;
    }
    std::cout << b << '\n';
    return 0;
}
